const input = $input.all();

const months = {
  January: 1,
  February: 2,
  March: 3,
  April: 4,
  May: 5,
  June: 6,
  July: 7,
  August: 8,
  September: 9,
  October: 10,
  November: 11,
  December: 12
};

function normalizeDate(dateText) {
  if (!dateText) return null;

  const match = dateText.match(
    /^([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th),\s*(\d{4})$/i
  );

  if (!match) return null;

  const monthName =
    match[1].charAt(0).toUpperCase() +
    match[1].slice(1).toLowerCase();

  const month = months[monthName];
  const day = Number(match[2]);
  const year = Number(match[3]);

  if (!month || !day || !year) return null;

  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

return input.map(item => {
  const data = { ...item.json };

  const startDate = normalizeDate(data.start_date_raw);
  const endDate = normalizeDate(data.end_date_raw);

  delete data.start_date_raw;
  delete data.end_date_raw;

  return {
    json: {
      ...data,
      start_date: startDate,
      end_date: endDate,
      date_precision: "day"
    }
  };
});

const input = $input.all();

const today = new Date();
today.setHours(0, 0, 0, 0);

return input.filter(item => {
  const endDate = item.json.end_date;

  if (!endDate) {
    return false;
  }

  const eventEnd = new Date(endDate + 'T00:00:00');
  eventEnd.setHours(0, 0, 0, 0);

  return eventEnd >= today;
});

const pageText = $input.first().json.page_text || '';

const upcomingSection =
  pageText.split('UPCOMING EVENTS 42')[1]?.split('PAST EVENTS')[0] || '';

const lines = upcomingSection
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

const events = [];

const sports = [
  'TABLE TENNIS',
  'PICKLE BALL',
  'FOOTBALL',
  'BASKETBALL',
  'BADMINTON',
  'SWIMMING',
  'ATHLETICS',
  'VOLLEYBALL',
  'GYMNASTICS',
  'ARCHERY',
  'FENCING',
  'CRICKET',
  'TENNIS',
  'SKATING',
  'SQUASH',
  'YOGA',
  'YOGASANA',
  'SHOOTING',
  'TAEKWONDO',
  'JUDO',
  'KARATE',
  'CHESS',
  'HANDBALL'
];

function getSport(eventName) {
  const upper = eventName.toUpperCase();

  return sports.find(sport =>
    upper.includes(sport)
  ) || '';
}

for (let i = 0; i < lines.length; i++) {

  const line = lines[i];

  const dateMatch = line.match(
    /([A-Z][a-z]+ \d{1,2}(?:st|nd|rd|th), \d{4})(?:\s*[–-]\s*([A-Z][a-z]+ \d{1,2}(?:st|nd|rd|th), \d{4}))?/
  );

  if (!dateMatch) continue;

  const startDateText = dateMatch[1];
  const endDateText = dateMatch[2] || dateMatch[1];

  const dateIndex = i;

  const blockStart = Math.max(0, dateIndex - 5);

  const block = lines.slice(blockStart, dateIndex);

  const cleanBlock = block.filter(
    x =>
      !x.startsWith('[https://') &&
      !x.startsWith('[images/') &&
      !x.startsWith('Reporting:')
  );

  if (cleanBlock.length < 2) continue;

  const eventName = cleanBlock[cleanBlock.length - 2];
  const category = cleanBlock[cleanBlock.length - 1];

  let location = '';

  for (
    let j = i + 1;
    j < Math.min(i + 4, lines.length);
    j++
  ) {
    if (
      !lines[j].startsWith('Reporting:') &&
      !lines[j].match(/^[A-Z][a-z]+ \d{1,2}/)
    ) {
      location = lines[j];
      break;
    }
  }

  const sport = getSport(eventName);

  const descriptionParts = [];

  if (eventName) {
    descriptionParts.push(eventName);
  }

  if (category) {
    descriptionParts.push(`Category: ${category}`);
  }

  if (location) {
    descriptionParts.push(`Location: ${location}`);
  }

  events.push({
    event_name: eventName || '',
    sport: sport,
    event_category: category || '',
    event_status: 'Upcoming',
    verification_status: 'Pending',
    source: 'ISSO',
    official_url: 'https://issoindia.com/events.php',
    Organizer: '',
    start_date_raw: startDateText,
    end_date_raw: endDateText,
    date_precision: 'day',
    location_raw: location,
    city: '',
    state: '',
    description: descriptionParts.join(' | ')
  });
}

return events.map(event => ({
  json: event
}));

