const input = $input.all();

const cityTostate = {
  'HYDERABAD': 'Telangana',
  'HYDERABAD CITY': 'Telangana',
  'HYD': 'Telangana',

  'AHMEDABAD': 'Gujarat',
  'RAIPUR': 'Chhattisgarh',
  'AJMER': 'Rajasthan',
  'FARIDABAD': 'Haryana',
  'GURUGRAM': 'Haryana',
