  'VISAKHAPATNAM': 'Andhra Pradesh',
  'VIJAYAWADA': 'Andhra Pradesh'
};

return input.map(item => {
  const data = { ...item.json };

  // Keep an existing State if already present
  const existingstate = String(data.state || '').trim();

  if (existingstate) {
    return {
      json: data
    };
  }

  // Read lowercase city
  const rawCity = String(data.city || '').trim();

  // Uppercase only for matching against the mapping
  const cityKey = rawCity.toUpperCase();

  const mappedstate = cityTostate[cityKey] || '';

  return {
    json: {
      ...data,
      state: mappedstate
    }
  };
});

const input = $input.all();

function formatCity(city) {
  return city
    .trim()
    .toLowerCase()
    .replace(/\b\w/g, char => char.toUpperCase());
}

return input.map(item => {
  const data = { ...item.json };

  const location = String(data.location_raw || '').trim();

  let venue = '';
  let city = '';

  if (location.includes(' - ')) {
    const parts = location
      .split(' - ')
      .map(part => part.trim())
      .filter(Boolean);

    if (parts.length >= 2) {
      city = formatCity(parts.pop());
      venue = parts.join(' - ');
    }
  } else if (location.includes(',')) {
    const parts = location
      .split(',')
      .map(part => part.trim())
      .filter(Boolean);

    if (parts.length >= 2) {
      city = formatCity(parts.pop());
      venue = parts.join(', ');
    }
  } else if (location) {
    city = formatCity(location);
    venue = '';
  }

  delete data.location_raw;

  return {
    json: {
      ...data,
      venue,
      city
    }
  };
});

const input = $input.all();

const seen = new Set();
const output = [];

for (const item of input) {
  const data = item.json;

  const eventName = String(data.event_name || '')
    .trim()
    .toLowerCase();

  const startDate = String(data.start_date || '').trim();

  const city = String(data.city || '')
    .trim()
    .toLowerCase();

  // Use event name + start date + city as duplicate key
  const key = `${eventName}|${startDate}|${city}`;

  if (!eventName || !startDate) {
    output.push(item);
    continue;
  }

  if (!seen.has(key)) {
    seen.add(key);
    output.push(item);
  }
}

return output;

const input = $input.all();

function formatDate(dateString) {
  if (!dateString) return '';

  const date = new Date(dateString + 'T00:00:00');

  if (isNaN(date.getTime())) return dateString;

  const day = date.getDate();

  const suffix =
    day >= 11 && day <= 13
      ? 'th'
      : day % 10 === 1
      ? 'st'
      : day % 10 === 2
      ? 'nd'
      : day % 10 === 3
      ? 'rd'
      : 'th';

  const month = date.toLocaleString('en-US', {
    month: 'long'
  });

  const year = date.getFullYear();

  return `${day}${suffix} ${month} ${year}`;
}

function cleanCategory(category) {
  if (!category) return '';

  return String(category)
    .trim()
    .toLowerCase()
    .replace(/\s*,\s*/g, ', ')
    .replace(/\s*&\s*/g, ' and ')
    .replace(/\bu(\d+)\b/gi, 'U$1')
    .replace(/\bunder\b/gi, 'Under')
    .replace(/\s+/g, ' ');
}

function cleanSport(sport) {
  return String(sport || '')
    .trim()
    .toLowerCase();
}

return input.map(item => {
  const data = { ...item.json };

  const eventName = String(data.event_name || '').trim();
  const category = cleanCategory(data.event_category);
  const sport = cleanSport(data.sport);
  const city = String(data.city || '').trim();
  const state = String(data.state || '').trim();

  const startDate = formatDate(data.start_date);
  const endDate = formatDate(data.end_date);

  let description = '';

  // Event name
  description += eventName;

  // Location
  if (city && state) {
    description += ` is organized in ${city}, ${state}`;
  } else if (city) {
    description += ` is organized in ${city}`;
  }

  // Dates
  if (startDate && endDate) {
    description += `, from ${startDate} to ${endDate}`;
  } else if (startDate) {
    description += `, on ${startDate}`;
  }

  // Category
  if (category) {
    description += ` for ${category}`;
  }

  description += '.';

  return {
    json: {
      ...data,
      description
    }
  };
});
